/**
 * Stable names for the REST schema types. They alias `./openapi.ts`, which is
 * hand-written today and generated by `pnpm generate:types` once the OpenAPI
 * document exists (#45). Keep the public names here unchanged when switching.
 *
 * @module
 */

import type { components } from "./openapi.js";

export type TokenResponse = components["schemas"]["TokenResponse"];
export type ConversationResponse = components["schemas"]["ConversationResponse"];
export type ConversationStatusResponse = components["schemas"]["ConversationStatusResponse"];
export type RestAttachment = components["schemas"]["Attachment"];
export type RestActivity = components["schemas"]["Activity"];
export type ActivitySet = components["schemas"]["ActivitySet"];
export type PostActivityRequest = components["schemas"]["PostActivityRequest"];
export type ResourceResponse = components["schemas"]["ResourceResponse"];
export type UploadResponse = components["schemas"]["UploadResponse"];
export type ErrorEnvelope = components["schemas"]["ErrorEnvelope"];
